<template>
 <div class="club-backdrop" :style="viewportStyle" @pointerdown.self="$emit('close')" @keydown.stop="keyboard" @keyup.stop>
  <section ref="panel" class="club-panel" :style="panelStyle" :class="{casino:tab==='roulette','house-expanded':newHouse,'ranking-expanded':tab==='board','house-preparing':duel?.phase==='preparation'}" role="dialog" aria-modal="true" aria-labelledby="club-title" data-whitepeak-panel>
   <header><span class="club-emblem" aria-hidden="true">{{ tab==='roulette'?'♧':'⚔' }}</span><div><small>BLANCHECIME</small><h2 id="club-title">{{ tab==='roulette'?'La table des neiges':tab==='board'?'Classement':tab==='watch'?'Regarder le duel':newHouse?'Maison des Combats':duel?.phase==='waiting'?'Combat préparé':'Organiser' }}</h2></div><button ref="close" aria-label="Fermer" @click="$emit('close')">×</button></header>
   <div class="club-body">
    <template v-if="tab==='roulette'">
     <div class="roulette-top"><roulette-wheel :state="roulette" :motion="motion"/><div class="roulette-info"><span class="phase-chip">{{ phaseLabel }}</span><h3>{{ roulette?.phase==='result'?`Le ${roulette.result} est sorti.`:roulette?.phase==='spinning'?'Les jeux sont faits.':'Faites vos jeux.' }}</h3><p>Le même tirage pour toute la salle.</p><b class="countdown" aria-live="off">{{ seconds }} s</b><p class="balance">Porte-monnaie <strong>{{ money(balance) }} ₽</strong></p></div></div>
     <div class="roulette-ticket"><label>Ta mise <span class="input-money"><input v-model.number="betAmount" data-roulette-amount type="number" inputmode="numeric" min="100" :max="allIn?balance:Math.min(balance,1000000)" @input="allIn=false" step="1" :disabled="busy||roulette?.phase!=='betting'"> ₽</span></label><button data-roulette-all-in :aria-pressed="allIn" :disabled="busy||!connected||roulette?.phase!=='betting'||seconds<=0||balance<100" @click="betAmount=balance;allIn=true">All-in</button><p>{{ allIn?'Tout ton solde sera misé. Choisis ta case, puis confirme avec Miser.':'100 ₽ minimum · 1 000 000 ₽ maximum, sauf All-in.' }}</p></div>
     <div class="outside-bets"><button v-for="c in outside" :key="c.kind" :class="c.kind" :aria-pressed="betChoice.kind===c.kind" :disabled="busy||roulette?.phase!=='betting'" @click="betChoice={kind:c.kind}">{{ c.name }} <small>×2</small></button></div>
     <div class="number-bets" aria-label="Choisir un numéro"><button v-for="n in numbers" :key="n" :class="{chosen:betChoice.kind==='number'&&betChoice.number===n}" :style="{background:color(n)}" :disabled="busy||roulette?.phase!=='betting'" :aria-pressed="betChoice.kind==='number'&&betChoice.number===n" @click="betChoice={kind:'number',number:n}">{{ n }}</button></div>
     <p class="club-help">Numéro exact : mise rendue ×36. Chances simples : ×2. Le zéro fait perdre les chances simples. Les gains indiqués comprennent la mise.</p>
     <section class="tickets"><h3>Autour de la table <small>{{ roulette?.bets?.length||0 }} mises</small></h3><p v-if="!roulette?.bets?.length" class="club-help">La table attend ses premiers joueurs.</p><div v-for="b in roulette?.bets||[]" :key="b.id" :class="{own:b.userId===userId}"><b>{{ b.username }}</b><span>{{ choiceName(b.choice) }} · {{ money(b.amount) }} ₽</span><strong v-if="roulette.phase==='result'">{{ b.payout?`+${money(b.payout)} ₽`:'—' }}</strong></div></section>
    </template>
    <template v-else-if="tab==='board'">
     <house-rankings :ranking="ranking" :user-id="userId" :busy="busy" @command="forwardCommand"/>
    </template>
    <template v-else>
     <battle-house-menu :raid-bosses="raidBosses" :raid-busy="raidBusy" :raid-error="raidError" @raid-catalog="$emit('raid-catalog')" @training="$emit('training',$event)" v-if="newHouse" :duel="duel" :rosters="rosters" :trainers="trainers" :user-id="userId" :busy="busy" :connected="connected" :clock="clock" @command="forwardCommand" @close="$emit('close')"/>
     <template v-else>
     <template v-if="!duel||duel.phase==='finished'">
      <div v-if="duel?.result" class="previous-result"><b>{{ resultText }}</b><p v-if="duel.result.wonPokemon">{{ duel.result.wonPokemon.name }} {{ duel.result.winnerId===userId?'a rejoint ton PC.':'rejoint le PC du vainqueur.' }}</p><p v-if="duel.config.money">{{ duel.result.refunded?'Les mises ont été rendues.':`Mise du duel : ${money(duel.config.money)} ₽ par joueur.` }}</p><p>Tes niveaux et tes ressources d’Aventure sont conservés.</p></div>
      <h3>Un duel à vos conditions</h3><p class="club-help">Organise le duel auprès de l’hôtesse, puis chaque dresseur rejoint l’un des deux socles. Les règles et les mises seront vérifiées avant vos confirmations.</p>
      <form class="duel-form" @submit.prevent="action('create',config)">
       <fieldset><legend>Règles de combat</legend><label>Niveau de tous les Pokémon<select v-model="config.level" data-duel-level><option :value="null">Libre · niveaux actuels</option><option v-for="level in [25,50,75,100]" :key="level" :value="level">Tous au niveau {{ level }}</option></select></label><label class="check"><input v-model="config.uniqueItems" type="checkbox">Objets uniques <small>Chaque objet tenu une seule fois par équipe.</small></label></fieldset>
       <fieldset><legend>Mises facultatives</legend><label>Pokédollars par joueur<input v-model.number="config.money" data-duel-money type="number" inputmode="numeric" min="0" max="1000000" step="100"></label><label class="check"><input v-model="config.pokemonStake" data-duel-pokemon-stake type="checkbox">Un Pokémon par joueur <small>Équipe ou PC · le vainqueur conserve le sien et reçoit celui de l’adversaire.</small></label></fieldset>
       <p class="club-help">Tous les Pokémon de l’équipe prennent le niveau choisi, en dessous comme au-dessus. L’équipe est soignée pour ce duel. Niveaux, PV, PP, statuts et objets de ton Aventure restent intacts. Le sac n’est pas utilisable pendant le combat.</p><button class="primary" data-create-duel :disabled="busy||!connected" type="submit">Organiser</button>
      </form>
     </template>
     <template v-else>
      <p v-if="duel.phase!=='waiting'" class="phase-chip">{{ duelPhase }}</p><div class="rule-summary"><b>{{ duel.config.level?`Niveau ${duel.config.level} pour tous`:'Niveaux libres' }}</b><span>{{ duel.config.uniqueItems?'Objets tenus uniques':'Objets tenus libres' }}</span><span>{{ duel.config.money?`${money(duel.config.money)} ₽ par dresseur`:'Sans mise d’argent' }}</span><span v-if="duel.config.pokemonStake">Un Pokémon en jeu</span></div>
      <div v-if="duel.phase==='review'" class="duel-players"><article v-for="(p,i) in duel.participants" :key="i" :class="{ready:p?.confirmed}"><small>SOCLE {{ i===0?'BLEU':'ROUGE' }}</small><h3>{{ p?.username||'Place libre' }}</h3><template v-if="p?.pokemon"><button class="pokemon-offer" data-club-inspect @click="inspect(p.pokemon)"><pokemon-portrait :src="sprite(p.pokemon)"/><span><strong>{{ p.pokemon.name }}</strong><small>Mise : niv. {{ p.pokemon.level }} · {{ p.pokemon.heldItemName||'Sans objet' }}</small><small v-if="duel.config.level" class="duel-level-hint">Duel au niveau {{ duel.config.level }}</small><potential-star :value="p.pokemon.potential"/></span><span class="inspect-hint">Voir la fiche</span></button></template><p v-else class="club-help">{{ duel.config.pokemonStake&&p?'Pokémon à choisir':'Monte sur ce socle pour participer.' }}</p><span v-if="p?.confirmed" class="confirmed">✓ Mise et duel acceptés</span></article></div>
      <section v-if="duel.phase==='waiting'" class="prepared-duel" data-prepared-duel>
       <p>{{ duel.hostId===userId?'Rejoins le socle bleu ou rouge, puis attends ton adversaire.':'Un combat est déjà préparé. Rejoins un socle libre pour y participer.' }}</p>
       <p v-if="duel.placementDeadline" class="placement-countdown" role="status">{{ duel.hostId===userId?'À toi de te placer':'Placement de l’organisateur' }} · {{ placementSeconds }} s</p>
       <p v-else class="club-help">L’organisateur est en place. Un adversaire peut rejoindre l’autre socle.</p>
       <ul><li v-for="(p,i) in duel.participants" :key="i"><span :class="i?'red-seat':'blue-seat'">●</span> Socle {{ i?'rouge':'bleu' }} · <b>{{ p?.username||'Libre' }}</b></li></ul>
      </section>
      <template v-if="duel.phase==='review'&&duel.you>=0&&duel.config.pokemonStake">
       <h3>Choisis le Pokémon que tu engages</h3><div class="pokemon-filter"><label>Emplacement<select v-model="box"><option value="team">Mon équipe</option><option v-for="n in duel.inventory?.boxCount||0" :key="n" :value="n-1">Boîte {{ n }}</option></select></label><label>Chercher<input v-model="query" type="search" placeholder="Nom du Pokémon"></label></div>
       <div class="pokemon-grid"><article v-for="p in candidates" :key="p.uuid" :class="{chosen:ownPokemon?.uuid===p.uuid}"><button :data-stake-pokemon="p.uuid" :disabled="busy||!!p.unavailableReason" @click="action('offer',{pokemonUuid:p.uuid})"><pokemon-portrait :src="sprite(p)"/><b>{{ p.name }}</b><small v-if="duel.config.level" class="duel-level-hint">Duel au niveau {{ duel.config.level }}</small><span>Mise : N. {{ p.level }} <potential-star :value="p.potential"/></span><small v-if="p.unavailableReason">{{ p.unavailableReason }}</small></button><button class="detail-button" :aria-label="`Fiche de ${p.name}`" @click="inspect(p)">Fiche</button></article><p v-if="!candidates.length">Aucun Pokémon à cet emplacement.</p></div>
      </template>
      <p v-if="duel.phase==='review'" class="wager-warning">Relis la fiche du Pokémon adverse avant d’accepter. Une déconnexion ou un abandon pendant le duel donne la victoire à l’adversaire. Une inscription annulée ne coûte rien ; une égalité rend les mises.</p>
      <button v-if="duel.canWatch&&tab==='watch'" class="primary" data-watch-duel :disabled="busy" @click="action('watch')">Regarder depuis les tribunes</button>
     </template>
     </template>
    </template>
   </div>
   <p v-if="error||(tab!=='board'&&duel?.error)" class="club-error" role="alert">{{ error||duel.error }}</p>
   <footer v-if="!newHouse"><template v-if="tab==='roulette'"><span>{{ choiceName(betChoice) }} · {{ money(betAmount||0) }} ₽</span><button class="primary" data-place-bet :disabled="!canBet" @click="placeBet">Miser</button></template><template v-else-if="tab!=='board'&&duel&&['waiting','review'].includes(duel.phase)"><button v-if="duel.you>=0||duel.hostId===userId" :disabled="busy" data-cancel-duel @click="cancel">Refuser / annuler</button><button v-if="duel.phase==='review'&&duel.you>=0" class="primary" data-confirm-duel :disabled="busy||!!duel.error||duel.participants[duel.you]?.confirmed||duel.config.pokemonStake&&duel.participants.some(p=>!p?.pokemon)" @click="action('confirm')">{{ duel.participants[duel.you]?.confirmed?'Adversaire attendu…':'Accepter les mises et combattre' }}</button></template><button v-else @click="$emit('close')">Retour dans la salle</button></footer>
  </section>
  <pokemon-details v-if="detail" class="club-details" :pokemon="detail" :position="1" :total="1" read-only :context-label="`POKÉMON MISÉ · NIVEAU D’ORIGINE${duel?.config?.level?` · COMBAT NIVEAU ${duel.config.level}`:''}`" footer-label="La mise conserve son niveau d’origine ; seul le combat applique le niveau choisi." @close="detail=null"/>
 </div>
</template>
<script>
import RouletteWheel from './RouletteWheel.vue';
import BattleHouseMenu from './BattleHouseMenu.vue';
import PokemonPortrait from '../PokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
import PokemonDetails from '../menu/PokemonDetails.vue';
import HouseRankings from './HouseRankings.vue';
import {computerPokemonDetails} from '@/services/pokemonComputer';
import {numberColor} from '@/services/whitepeakRoulette';
const outside=[{kind:'red',name:'Rouge'},{kind:'black',name:'Noir'},{kind:'even',name:'Pair'},{kind:'odd',name:'Impair'},{kind:'low',name:'1 à 18'},{kind:'high',name:'19 à 36'}];
export default{
 components:{HouseRankings,BattleHouseMenu,RouletteWheel,PokemonPortrait,PotentialStar,PokemonDetails},
 props:{raidBosses:Array,raidBusy:Boolean,raidError:String,ranking:Object,rosters:Object,trainers:{type:Array,default:()=>[]},tab:String,roulette:Object,duel:Object,balance:Number,userId:Number,busy:Boolean,error:String,connected:Boolean,motion:Boolean,rows:{type:Array,default:()=>[]}},
 data:()=>({viewportHeight:window.innerHeight,viewportTop:0,config:{level:null,uniqueItems:false,money:0,pokemonStake:false},betAmount:100,allIn:false,betChoice:{kind:'red'},box:'team',query:'',detail:null,clock:Date.now(),pendingBet:null}),
 computed:{panelStyle(){const available=Math.max(0,this.viewportHeight-24);return{maxHeight:available+'px',height:this.newHouse||this.tab==='board'?Math.min(this.tab==='board'?850:900,available)+'px':'auto'};},viewportStyle(){return{'--club-viewport-height':this.viewportHeight+'px',height:this.viewportHeight+'px',top:this.viewportTop+'px',bottom:'auto'};},newHouse(){return !['roulette','board'].includes(this.tab)&&(!this.duel||this.duel.phase==='finished'||this.duel.advanced);},outside:()=>outside,numbers:()=>Array.from({length:37},(_,i)=>i),phaseLabel(){return{betting:'Mises ouvertes',spinning:'Tirage en cours',result:'Résultat partagé'}[this.roulette?.phase]||'La table se prépare';},seconds(){const s=this.roulette;if(!s)return 0;return Math.max(0,Math.ceil(((s.phase==='betting'?s.closesAt:s.phase==='spinning'?s.resultAt:s.nextAt)-this.clock-(s.serverOffset||0))/1000));},
 placementSeconds(){return Math.max(0,Math.ceil((this.duel.placementDeadline-this.clock-(this.duel.serverOffset||0))/1000));},
 canBet(){return this.connected&&!this.busy&&this.roulette?.phase==='betting'&&this.seconds>0&&Number.isSafeInteger(this.betAmount)&&this.betAmount>=100&&this.betAmount<=(this.allIn?this.balance:Math.min(this.balance,1000000))&&(!this.allIn||this.betAmount===this.balance);},
 duelPhase(){return{waiting:'Combat préparé',review:'Vérifier les mises',starting:'Inscription du duel…',battle:'Duel en cours',settling:'Sauvegarde du résultat…'}[this.duel?.phase]||'';},
 candidates(){const i=this.duel?.inventory;const all=this.box==='team'?i?.team||[]:(i?.entries||[]).filter(e=>e.box===Number(this.box)).map(e=>e.pokemon);return all.filter(p=>String(p.name).toLocaleLowerCase().includes(this.query.toLocaleLowerCase()));},
 ownPokemon(){return this.duel?.participants[this.duel.you]?.pokemon;},resultText(){const r=this.duel?.result;if(!r)return'';const winner=this.duel.participants.find(p=>p?.userId===r.winnerId);return winner?`${winner.username} remporte le duel.`:'Le duel est terminé. Les mises ont été rendues.';}},
 mounted(){this.syncViewport();window.addEventListener('resize',this.syncViewport);window.visualViewport?.addEventListener('resize',this.syncViewport);window.visualViewport?.addEventListener('scroll',this.syncViewport);this.previousFocus=document.activeElement;this.$refs.close.focus();this.timer=setInterval(()=>{this.clock=Date.now();},250);},beforeDestroy(){window.removeEventListener('resize',this.syncViewport);window.visualViewport?.removeEventListener('resize',this.syncViewport);window.visualViewport?.removeEventListener('scroll',this.syncViewport);clearInterval(this.timer);if(this.previousFocus?.isConnected)this.previousFocus.focus({preventScroll:true});},
 methods:{syncViewport(){this.viewportHeight=Math.min(window.innerHeight,window.visualViewport?.height||window.innerHeight);this.viewportTop=Math.max(0,Math.min(window.visualViewport?.offsetTop||0,window.innerHeight-this.viewportHeight));},forwardCommand(...args){this.$emit('command',...args);},money:n=>Number(n||0).toLocaleString('fr-FR'),color:numberColor,sprite(p){return this.$pokemonSprite(p);},inspect(p){this.detail=computerPokemonDetails(p);},choiceName(c){return c.kind==='number'?`Numéro ${c.number}`:outside.find(i=>i.kind===c.kind)?.name||'';},
 action(name,data={}){this.$emit('command',name,{id:this.duel?.id,revision:this.duel?.revision,...data});},
 placeBet(){const signature=JSON.stringify({roundId:this.roulette.id,amount:this.betAmount,choice:this.betChoice,allIn:this.allIn});if(this.pendingBet?.signature!==signature)this.pendingBet={signature,id:crypto.randomUUID()};this.$emit('command','bet',{id:this.pendingBet.id,roundId:this.roulette.id,amount:this.betAmount,choice:this.betChoice,allIn:this.allIn},success=>{if(success)this.pendingBet=null;});},
 cancel(){if(window.confirm('Annuler cette inscription ? Aucun argent ni Pokémon ne sera transféré.'))this.action('leave');},
 keyboard(e){if(e.key==='Escape'){e.preventDefault();if(this.detail)this.detail=null;else this.$emit('close');}if(e.key==='Tab'&&!this.detail){const nodes=[...this.$refs.panel.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
 }
};
</script>
<style scoped>
.roulette-ticket{display:flex;align-items:end;flex-wrap:wrap;gap:8px 12px}.roulette-ticket>label{flex:1;min-width:140px}.roulette-ticket>p{flex-basis:100%;margin-top:0}.roulette-ticket>[data-roulette-all-in]{min-height:46px;color:var(--journal-accent);font-weight:800;background:var(--journal-selected)}

.club-backdrop{transition-property:none!important;animation-name:none!important;box-sizing:border-box;grid-template-rows:minmax(0,1fr);position:fixed;inset:0;z-index:3400;display:grid;place-items:center;padding:12px;background:var(--journal-backdrop);color:var(--journal-ink);font:14px/1.5 var(--journal-font)}
